parameters.jsCode:
const data = $json.body || $json;
const results = [];

function detectSource(data) {
  if (data.object === "whatsapp_business_account") return "whatsapp";
  if (data.object === "instagram") return "instagram";
  if (data.object === "page") return "facebook";
  return "unknown";
}

function normalizeFacebookOrInstagramMessaging(data) {
  for (const entry of data.entry || []) {
    for (const event of entry.messaging || []) {
      results.push({
        source: detectSource(data),
        eventType: "message",
        senderId: event.sender?.id || null,
        recipientId: event.recipient?.id || null,
        messageId: event.message?.mid || null,
        message: event.message?.text || "",
        timestamp: event.timestamp || entry.time || null,
        replyTo: event.sender?.id || null,
        raw: event
      });
    }
  }
}

function normalizeFacebookFeed(data) {
  for (const entry of data.entry || []) {
    for (const change of entry.changes || []) {
      if (change.field !== "feed") continue;

      const value = change.value || {};

      results.push({
        source: "facebook",
        eventType: value.item || "feed",
        feedVerb: value.verb || null,
        senderId: value.from?.id || null,
        senderName: value.from?.name || null,
        recipientId: entry.id || null,
        messageId: value.comment_id || value.post_id || null,
        message: value.message || "",
        timestamp: value.created_time || entry.time || null,

        postId: value.post_id || value.post?.id || null,
        commentId: value.comment_id || null,
        parentId: value.parent_id || null,
        permalinkUrl: value.post?.permalink_url || null,

        replyTo: value.comment_id || value.post_id || null,
        raw: change
      });
    }
  }
}

function normalizeWhatsApp(data) {
  for (const entry of data.entry || []) {
    for (const change of entry.changes || []) {
      const value = change.value || {};

      // Get contact profile name if available
      const contact = value.contacts?.[0] || {};
      const senderName = contact.profile?.name || null;

      for (const message of value.messages || []) {
        results.push({
          source: "whatsapp",
          eventType: "message",

          phoneNumber: message.from || null,
          senderName: senderName,

          recipientId: value.metadata?.phone_number_id || null,
          messageId: message.id || null,
          message: message.text?.body || "",
          timestamp: message.timestamp || null,

          replyTo: message.from || null,
          phoneNumberId: value.metadata?.phone_number_id || null,

          raw: message
        });
      }
    }
  }
}

if (data.object === "whatsapp_business_account") {
  normalizeWhatsApp(data);
} else {
  normalizeFacebookOrInstagramMessaging(data);
  normalizeFacebookFeed(data);
}

return results.map(item => ({ json: item }));

